def handle_feed_request(user_id, region):
    profile = redis_profile.get(user_id, timeout_ms=4)
    cands = retrieve_parallel(profile, region, timeout_ms=10)
    if not cands:
        return trending_fallback.get(region, limit=10)
    return rank_and_diversify(profile, cands)

def index_new_article(article):
    vec = item_tower.encode(article['title'], article['body'])
    for shard in hnsw_shards:
        shard.upsert_delta(article['id'], vec)
    trending_zset.zadd(article['region'], {article['id']: time.time()})

def filter_seen_candidates(user_bloom, candidates):
    unseen = [c for c in candidates if c['id'] not in user_bloom]
    if len(unseen) < 20:
        return candidates[:50]  # Safety valve if user exhausted feed
    return unseen

def score_batch_tensorrt(user_feats, item_feats_matrix, model):
    # Broadcast user_feats once instead of repeating 1000x over PCIe
    try:
        return model.infer_fp16(user_feats, item_feats_matrix)
    except CudaOutOfMemoryError:
        return lightgbm_cpu_fallback.predict(item_feats_matrix)

def thompson_sample_score(clicks, impressions, prior_alpha=1.0, prior_beta=20.0):
    alpha = prior_alpha + clicks
    beta = prior_beta + max(0, impressions - clicks)
    return random.betavariate(alpha, beta)

def promote_model_if_healthy(new_ndcg, prod_ndcg, calibration_err):
    if new_ndcg >= prod_ndcg * 0.995 and calibration_err < 0.03:
        registry.deploy_canary('deepfm_hourly', traffic_pct=5)
        return True
    return False
